func (t *ProfileTotals) add(e Event) {
	if e.Value != nil {
		t.Value.add(*e.Value)
		t.Valued = true
	}
	t.Requests++
	addTokens(&t.Tokens, e.Tokens)
	if e.Failed {
		t.Failed++
	}
	if e.CostNano == nil {
		t.Unpriced++
	} else {
		t.CostNano += *e.CostNano
	}
}

